<script setup lang="ts">
import type {Product,ProductStatus} from '~/shared/types'
const props=defineProps<{productId?:string}>(),api=useApi(),busy=ref(false),message=ref(''),error=ref(''),confirmDelete=ref(false)
const {data:categories}=await useAsyncData('categories',()=>api.categories())
const {data:collections}=await useAsyncData('collections',()=>api.collections())
const blank:Product={id:'',slug:'',name:'',shortDescription:'',description:'',category:'clothing',collectionIds:[],tags:[],images:[],price:0,currency:'RUB',variants:[{id:crypto.randomUUID(),sku:'',size:'',color:'',stock:10,available:true}],status:'draft',isFeatured:false,publishedAt:null,createdAt:'',updatedAt:''}
const {data:existing,error:loadError,pending:loading,refresh}=await useAsyncData(()=>`edit-${props.productId||'new'}`,()=>props.productId?api.adminProduct(props.productId):Promise.resolve(blank))
if(loadError.value&&(loadError.value as {statusCode?:number}).statusCode===404)throw createError({statusCode:404,statusMessage:'Товар не найден'})
const form=reactive<Product>(JSON.parse(JSON.stringify(existing.value||blank))),priceRub=ref(form.price/100),tags=ref(form.tags.join(', ')),asset=ref(form.images[0]?.url||'')
const assets=['hoodie','tee','keychain','poster','archivist','compass','notebook']
const statuses:Record<string,string>={draft:'Черновик',published:'Опубликован',archived:'В архиве'}
watch(existing,value=>{if(value){Object.assign(form,JSON.parse(JSON.stringify(value)));priceRub.value=value.price/100;tags.value=value.tags.join(', ');asset.value=value.images[0]?.url||''}})
function choose(url:string){asset.value=url;form.images=[{url,alt:form.name||'Демонстрационное изображение товара'}]}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>1024*1024){error.value='Выберите JPEG, PNG или WebP размером до 1 МБ.';return}const reader=new FileReader();reader.onload=()=>{choose(String(reader.result));error.value=''};reader.readAsDataURL(file)}
function addVariant(){form.variants.push({id:crypto.randomUUID(),sku:'',size:'',color:'',stock:0,available:true})}
async function save(status?:ProductStatus){if(busy.value)return;busy.value=true;message.value='';error.value='';try{const body=JSON.parse(JSON.stringify(form)) as Product;body.price=Math.round(Number(priceRub.value)*100);body.tags=tags.value.split(',').map(s=>s.trim()).filter(Boolean);if(status)body.status=status;for(const image of body.images)if(!image.alt)image.alt=body.name;const saved=await api.saveProduct(body,props.productId);Object.assign(form,saved);message.value=`Сохранено · ${statuses[saved.status]}`;clearNuxtData(k=>k.startsWith('home-')||k.startsWith('catalog-')||k.startsWith('admin-products')||k==='collection-products');if(!props.productId)await navigateTo(`/admin/products/${saved.id}`)}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function remove(){busy.value=true;confirmDelete.value=false;try{await api.deleteProduct(props.productId!);clearNuxtData();await navigateTo('/admin/products')}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
</script>
<template><div><ApiState :pending="loading" :error="loadError" @retry="refresh()"/><form v-if="!loading&&!loadError" class="admin-form form-stack" @submit.prevent="save()"><section class="form-panel"><h2>Основные сведения</h2><div class="form-grid"><label class="field">Название *<input v-model="form.name" required maxlength="120" placeholder="Например, худи «Архив»"></label><label class="field">Slug — адрес латиницей *<input v-model="form.slug" required pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="120" placeholder="archive-hoodie"></label><label class="field">Категория *<select v-model="form.category" required><option v-for="c in categories" :key="c.id" :value="c.slug">{{c.name}}</option></select></label><label class="field">Цена, ₽ *<input v-model.number="priceRub" type="number" min="0" max="1000000" step="0.01" required></label><label class="field full">Краткое описание<textarea v-model="form.shortDescription" maxlength="500" style="min-height:65px"/></label><label class="field full">Полное описание<textarea v-model="form.description" maxlength="10000"/></label><label class="field full">Теги через запятую<input v-model="tags" placeholder="архив, хлопок, символ семьи"></label></div></section><section class="form-panel"><h2>Изображения</h2><p class="sidebar-label">Выберите готовый кадр</p><div class="asset-picker"><button v-for="a in assets" :key="a" type="button" :class="{selected:asset===`/assets/${a}.webp`}" :aria-label="`Выбрать изображение ${a}`" @click="choose(`/assets/${a}.webp`)"><img :src="`/assets/${a}.webp`" :alt="a" width="100" height="80"></button></div><img v-if="asset" class="image-preview" :src="asset" alt="Предпросмотр основного изображения"><div v-if="form.images.length" style="margin:15px 0"><label class="field">Альтернативный текст<input v-model="form.images[0]!.alt" maxlength="200" placeholder="Описание товара на фото"></label><button class="text-link" type="button" style="margin-top:10px" @click="form.images=[];asset=''">Убрать изображение</button></div><label class="field" style="margin-top:18px">Или локальный файл — JPEG, PNG, WebP до 1 МБ<input type="file" accept="image/jpeg,image/png,image/webp" @change="upload"></label><p style="font-size:10px;color:var(--muted);margin-top:10px">Кадр хранится только в памяти демо-сессии. Постоянная загрузка файлов не подключена.</p></section><section class="form-panel"><h2>Варианты и остатки</h2><div v-for="(v,i) in form.variants" :key="v.id" class="variant-editor"><label class="field">Уникальный SKU *<input v-model="v.sku" required maxlength="80" placeholder="DF-ARCHIVE-M"></label><label class="field">Размер<input v-model="v.size" maxlength="40" placeholder="M"></label><label class="field">Цвет<input v-model="v.color" maxlength="60" placeholder="Угольный"></label><label class="field">Остаток *<input v-model.number="v.stock" type="number" min="0" max="9999" required></label><label class="check-label"><input v-model="v.available" type="checkbox">Доступен</label><button type="button" class="icon-button" :disabled="form.variants.length===1" :aria-label="`Удалить вариант ${i+1}`" @click="form.variants.splice(i,1)"><AppIcon name="trash" :size="18"/></button><label class="field" style="grid-column:span 2">Цена варианта, ₽ (пусто = основная)<input :value="v.price===undefined?'':v.price/100" type="number" min="0" max="1000000" step="0.01" @input="v.price=($event.target as HTMLInputElement).value===''?undefined:Math.round(Number(($event.target as HTMLInputElement).value)*100)"></label></div><button type="button" class="btn btn-small" style="margin-top:18px" :disabled="form.variants.length>=40" @click="addVariant"><AppIcon name="plus" :size="15"/>Добавить вариант</button></section><section class="form-panel"><h2>Публикация и подборки</h2><div class="form-grid"><label class="field">Статус<select v-model="form.status"><option value="draft">Черновик</option><option value="published">Опубликован</option><option value="archived">В архиве</option></select></label><label class="check-label"><input v-model="form.isFeatured" type="checkbox">Рекомендуемый товар (Featured)</label><div class="full"><p class="sidebar-label">Коллекции</p><div style="display:flex;gap:20px;flex-wrap:wrap"><label v-for="c in collections" :key="c.id" class="check-label"><input v-model="form.collectionIds" type="checkbox" :value="c.id">{{c.name}}</label></div></div></div></section><p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="message" class="notice success" role="status">{{message}}</p><div class="form-actions"><button type="submit" class="btn btn-primary" :disabled="busy">{{busy?'Сохраняем…':'Сохранить изменения'}}</button><button type="button" class="btn" :disabled="busy" @click="save('draft')">Сохранить черновик</button><button type="button" class="btn" :disabled="busy" @click="save('published')">Опубликовать</button><button v-if="productId" type="button" class="btn" :disabled="busy" @click="save('archived')">В архив</button><NuxtLink v-if="form.status==='published'&&productId" :to="`/products/${form.slug}`" class="text-link">В магазине <AppIcon name="arrow" :size="15"/></NuxtLink><button v-if="productId" type="button" class="btn btn-danger" :disabled="busy" @click="confirmDelete=true">Удалить</button></div></form><ConfirmDialog v-if="confirmDelete" title="Удалить товар?" message="Товар исчезнет из архива этой сессии. Это действие нельзя отменить без сброса всех демо-данных." confirm-label="Удалить товар" @cancel="confirmDelete=false" @confirm="remove"/></div></template>
